import collections,sys
out=sys.argv[1]
H=["#","文献","场景","来流","耦合","闭环","尺度","流场","旋翼","验证","计入","备注"]
L=["# L22.7 综述分类表 v2.2（v2.1 ＋ 10-22 引文滚雪球两轮补录 #48–70）","",
"来源：Deep Research ec4601 ＋ Gemini 联网扩充 #dd0a0d49 ＋ 审查 f328c559 三位审稿人补漏与纠错 ＋ Lead 抽核。标签由 Lead 判定（工单0204）。'?'=未读到原文。",
"计入数值统计：外部障碍物（建筑/城市、地面障碍物、舰船、风电场）或近壁/台阶与旋翼**同时出现**的数值研究；期刊重复版、综述、身份不完整、纯试验、纯尾流（无旋翼）、旋翼–机身/机翼干扰、非 CFD 模型、非旋翼机标 N。","",
"| "+" | ".join(H)+" |","|"+"---|"*len(H)]
for r in R: L.append("| "+" | ".join(r)+" |")
inn=[r for r in R if r[10]=="Y"]
L+=["",f"## 计数（脚本生成：列出 {len(R)} 条，计入 {len(inn)} 条）",""]
for name,i in [("场景",2),("来流",3),("耦合",4),("闭环",5),("尺度",6)]:
    c=collections.Counter(r[i] for r in inn); L.append(f"- {name}："+"；".join(f"{k} {v}" for k,v in c.most_common()))
L+=["","## 交叉：场景 × 来流 × 耦合 × 闭环","","| 场景 | 来流 | 耦合 | 闭环 | 篇数 | 编号 |","|---|---|---|---|---|---|"]
g=collections.defaultdict(list)
for r in inn: g[(r[2],r[3],r[4],r[5])].append(r[0])
for k in sorted(g): L.append(f"| {k[0]} | {k[1]} | {k[2]} | {k[3]} | {len(g[k])} | {','.join(g[k])} |")
L+=["","## 关键组合（脚本检索）",""]
def q(desc,f):
    ids=[r[0] for r in inn if f(r)]; L.append(f"- {desc}：{len(ids)} 条 {','.join(ids) if ids else '（未检索到）'}")
q("建筑/城市 + 有来流 + 双向",lambda r:r[2]=="建筑/城市" and r[3]=="有" and r[4]=="双向")
q("建筑/城市 + 有来流 + 双向 + 小型多旋翼",lambda r:r[2]=="建筑/城市" and r[3]=="有" and r[4]=="双向" and r[6]=="小型多旋翼")
q("建筑/城市 + 有来流 + 双向 + 闭环",lambda r:r[2]=="建筑/城市" and r[3]=="有" and r[4]=="双向" and r[5]=="有")
q("任何场景 + 双向 + 闭环",lambda r:r[4]=="双向" and r[5]=="有")
q("LBM + 双向 + 闭环",lambda r:"LBM" in r[7] and r[4]=="双向" and r[5]=="有")
q("有来流 + 双向 + 风洞/试验验证（任何尺度；验证须含有风工况）",lambda r:r[3]=="有" and r[4]=="双向" and any(k in r[9] for k in ("风洞","试验","PIV")) and "仅无风" not in r[9])
q("有来流 + 双向 + 风洞/试验验证 + 小型多旋翼",lambda r:r[3]=="有" and r[4]=="双向" and r[6]=="小型多旋翼" and any(k in r[9] for k in ("风洞","试验","PIV")))
q("建筑/城市 + 单向 + 小型多旋翼 + 飞行试验验证",lambda r:r[2]=="建筑/城市" and r[4]=="单向" and r[6]=="小型多旋翼" and "飞行试验" in r[9])
q("LBM + 致动线",lambda r:"LBM" in r[7] and "致动线" in r[8])
open(out,"w",encoding="utf-8").write("\n".join(L)+"\n")
print("\n".join(L[L.index(f"## 计数（脚本生成：列出 {len(R)} 条，计入 {len(inn)} 条）"):]))
